CREATE TYPE "MobileDeploymentStatus" AS ENUM ('RIDER_WAITING','FLEET_REQUESTED','PAYMENT_PENDING','PAYMENT_PAID','PDI_PENDING_RIDER','TRAINING_PENDING','DEVICE_PAIRING_PENDING','DEPLOYED');
CREATE TABLE "MobileDeploymentWorkflow" ("id" TEXT NOT NULL,"clientId" TEXT NOT NULL,"allocationId" TEXT NOT NULL,"status" "MobileDeploymentStatus" NOT NULL DEFAULT 'RIDER_WAITING',"paymentBreakdown" JSONB,"paymentPaidAt" TIMESTAMP(3),"pdiChecklist" JSONB,"riderPdiAcceptedAt" TIMESTAMP(3),"riderPdiRemarksText" TEXT,"riderPdiVoicePhotoId" TEXT,"trainingCompletedAt" TIMESTAMP(3),"pairedAt" TIMESTAMP(3),"pairingBypassedAt" TIMESTAMP(3),"pairingBypassedById" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "MobileDeploymentWorkflow_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MobileDeploymentWorkflow_allocationId_key" ON "MobileDeploymentWorkflow"("allocationId");
CREATE INDEX "MobileDeploymentWorkflow_clientId_status_idx" ON "MobileDeploymentWorkflow"("clientId","status");
ALTER TABLE "MobileDeploymentWorkflow" ADD CONSTRAINT "MobileDeploymentWorkflow_allocationId_fkey" FOREIGN KEY ("allocationId") REFERENCES "Allocation"("id") ON DELETE CASCADE ON UPDATE CASCADE;
